@* The page owns the tasks and the transport; the surface paints them and reports intent. *@
<TmFanOutGrid Tasks="_tasks"
              Title="Reconcile 40 invoices"
              Columns="4"
              @bind-Filter="_filter"
              OnRetry="RetryAsync"
              OnCancel="CancelAsync" />

@code {
    private IReadOnlyList<FanOutTask> _tasks = [];
    private FanOutFilter _filter = FanOutFilter.All;

    private Task RetryAsync(FanOutTask task)
    {
        _tasks = [.. _tasks.Select(t => t.Id == task.Id
            ? t with { Status = AgentActivityStatus.Queued, Attempt = t.Attempt + 1, Error = null }
            : t)];
        return Task.CompletedTask;
    }

    private Task CancelAsync(FanOutTask task)
    {
        _tasks = [.. _tasks.Select(t => t.Id == task.Id
            ? t with { Status = AgentActivityStatus.Cancelled }
            : t)];
        return Task.CompletedTask;
    }
}

var task = new FanOutTask("region-7", "Region 7")
{
    Status = AgentActivityStatus.Running,
    Worker = new AgentRef("Fetcher", "w-1") { ColorIndex = 1 },
    Attempt = 2,
    MaxAttempts = 3,
    StartedAt = now.AddMinutes(-2),
    EstimatedEndAt = now.AddSeconds(42),
    CostMicroUnits = 120_000,
};

// "Attempt 2/3", a live 0:42 countdown, and a Retry once it fails.
